
public class primitiveDatatype {
	public static void main(String[] args) {
		// TODO Auto-generated method stub
		boolean b1=true;
		boolean b2=false;
		System.out.println("Boolean datatype values are :"+b1+b2);
		
		char c='A';
		System.out.println("Character datatype value is :"+c);
		
		byte b=74;          //maximum 2 bit
		System.out.println("byte datatype value is :"+b);
		
		short n1=12343;    //maximum 5 bit
		System.out.println("short datatype value is :"+n1);
		
		int n2=743434244;   //maximum 9 bit
		System.out.println("integer datatype value is :"+n2);
		
		long n3=7343674835446445799L; //maximum 19 bit
		System.out.println("long datatype value is :"+n3);
		
		float f=127.56f;
		System.out.println("float datatype value is :"+f);
		
		double d=747467.764674754657845478D;
		System.out.println("double datatype value is :"+d);
		
		
		

	}


}
